CREATE OR REPLACE FUNCTION security.ai_spend_capture_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
-- Decision 5 E-7 (2 Nov 2026): records the AI cost a row gains. tg_argv: lane, how ('delta' = the increase of an accumulated cost;
-- 'decision' = the cost of each decision of a leased item, as svc_coverage_ai_match_record overwrites it), the path of the cost in the row.
declare v_new jsonb := to_jsonb(new); v_old jsonb := case when tg_op = 'UPDATE' then to_jsonb(old) end; v_path text[] := tg_argv[2]::text[];
        v_add numeric;
begin
  if tg_argv[1] = 'decision' then
    if tg_op = 'UPDATE' and not (v_old->>'state' = 'leased' and v_new->>'state' <> 'leased'
                                 and (v_new->>'decided_at') is distinct from (v_old->>'decided_at')) then return null; end if;
    v_add := coalesce((v_new #>> v_path)::numeric, 0);
  else
    v_add := coalesce((v_new #>> v_path)::numeric, 0) - coalesce((v_old #>> v_path)::numeric, 0);
  end if;
  if v_add > 0 then
    insert into pipeline.ai_spend_ledger(lane, source, source_id, cost_usd) values (tg_argv[0], tg_table_name, v_new->>'id', v_add);
  end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION security.course_description_review_trg_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_item bigint := case when coalesce(new.proposed_value->>'item_id', '') ~ '^\d+$' then (new.proposed_value->>'item_id')::bigint end; v_pid uuid;
begin
  if v_item is not null then
    update pipeline.field_enrich_items set state = case when new.status in ('approved', 'edited_approved') then 'filled' else 'skipped' end,
           reason = case when new.status in ('approved', 'edited_approved') then null else 'not admitted in Layer 4 (' || new.status || ')' end, updated_at = now()
     where id = v_item and state = 'review';
  end if;
  if new.status in ('approved', 'edited_approved') then
    select c.provider_id into v_pid from catalogue.courses c where c.id = new.entity_id;
    perform security.course_description_release_held_v1(v_pid);
    insert into search.refresh_requests(requested_by) select 'AI reader (course description, deadline)'
     where not exists (select 1 from search.refresh_requests q where q.processed_at is null and q.requested_by = 'AI reader (course description, deadline)');
  end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION security.coverage_page_refused_host_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_new_evidence boolean := false; v_chk jsonb;
begin
  -- 31 Oct 2026 (StudySearch SS-007): a course under a binding remediation hold keeps its binding until a person lifts the hold
  if tg_op = 'UPDATE' and new.status in ('bound', 'ambiguous') and security.course_held_v1(new.course_id)
     and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = new.course_id and k.field = 'official_url') then
    return old;
  end if;
  if new.status in ('bound', 'ambiguous') and security.refused_host(new.url)
     and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = new.course_id and k.field = 'official_url') then
    new.status := 'mismatch'; new.read_status := 'refused_host'; new.identity_basis := null; new.next_read_at := null;
  -- 21 Oct 2026 (Platform Admin "Go on with task 3"): never a course page (setting pages.not_course_patterns)
  elsif new.status in ('bound', 'ambiguous') and security.not_course_page_v1(new.url)
     and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = new.course_id and k.field = 'official_url') then
    new.status := 'mismatch'; new.read_status := 'not_course_page'; new.identity_basis := null; new.next_read_at := null;
  end if;
  -- 2 Nov 2026 (E16-1, Platform Admin 07:21): the page must not contradict this course (security.course_page_check_v1), whichever lane binds
  -- it. Checked when a page is bound or re-bound, when it is first read, or when its identity proof changes; a page set by hand is not.
  if new.status in ('bound', 'ambiguous') and coalesce(new.basis, '') <> 'manual' and security.pipeline_num_v1('binding.identity_check', 1) >= 1
     and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = new.course_id and k.field in ('official_url', 'course_url')) then
    if tg_op = 'INSERT' then
      v_new_evidence := true;
    else
      v_new_evidence := new.url is distinct from old.url or old.status not in ('bound', 'ambiguous') or new.identity_basis is distinct from old.identity_basis
                        or (new.read_status = 'read' and old.read_status is distinct from 'read');
    end if;
    -- a page already rejected or blocked for this course (pipeline.page_rejections, pipeline.course_page_blocks) is refused by every lane
    if v_new_evidence and security.page_refused_v1(new.course_id, new.url) then
      new.status := 'mismatch'; new.read_status := 'page_refused'; new.identity_basis := null; new.next_read_at := null;
      v_new_evidence := false;
    end if;
    if v_new_evidence then
      v_chk := security.course_page_check_v1(new.course_id, coalesce(nullif(new.candidates->>'final_url', ''), new.url),
                                             coalesce(nullif(new.candidates->>'page_title', ''), new.candidates->>'h1'), new.identity_basis);
      if v_chk->>'verdict' = 'refuse' then
        perform security.binding_refusal_route_v1(new.course_id, new.url, v_chk, coalesce(new.basis, 'unknown'), new.evidence_id);
        new.status := 'mismatch'; new.read_status := 'identity_refused'; new.identity_basis := null; new.next_read_at := null;
      end if;
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION security.cricos_identity_guard_trg_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
-- Trigger coverage_page_refused_host_zz_cricos (after coverage_page_refused_host, the E16 guard). While binding.cricos_identity_guard_on is 1:
-- a binding (bound or ambiguous) whose identity basis is a title (binding.title_identity_bases), not set by hand and not on a course locked by
-- hand, whose page is the CRICOS-proved page of another active course of the provider, is refused as E16 refuses: the refusal is recorded and
-- routed (security.binding_refusal_route_v1), status mismatch, read_status cricos_identity_refused. Checked only when the binding, its address
-- or its identity basis changes.
declare v_c jsonb; v_codes text;
begin
  if security.pipeline_num_v1('binding.cricos_identity_guard_on', 0) < 1 then return new; end if;
  if new.status not in ('bound', 'ambiguous') or coalesce(new.basis, '') = 'manual'
     or not (coalesce(new.identity_basis, '') = any (security.pipeline_list_v1('binding.title_identity_bases', '[]'::jsonb))) then return new; end if;
  if tg_op = 'UPDATE' and new.url is not distinct from old.url and new.status is not distinct from old.status and new.identity_basis is not distinct from old.identity_basis then
    return new;
  end if;
  if exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = new.course_id and k.field in ('official_url', 'course_url')) then return new; end if;
  v_c := security.cricos_identity_conflict_v1(new.course_id, coalesce(nullif(new.candidates->>'final_url', ''), new.url), new.candidates->>'text_sha');
  if not coalesce((v_c->>'conflict')::boolean, false) then return new; end if;
  select string_agg(x->>'code', ', ') into v_codes from jsonb_array_elements(v_c->'courses') x;
  perform security.binding_refusal_route_v1(new.course_id, new.url,
            jsonb_build_object('verdict', 'refuse', 'rule', 'cricos_identity',
                               'reason', 'the page states the CRICOS code of another course (' || v_codes || '), and this course matched it by title only', 'checks', v_c),
            coalesce(new.basis, 'unknown'), new.evidence_id);
  new.status := 'mismatch'; new.read_status := 'cricos_identity_refused'; new.identity_basis := null; new.next_read_at := null;
  return new;
end $function$

CREATE OR REPLACE FUNCTION security.layer4_arrival_guard_trg_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
-- Trigger layer4_review_items_zz_arrival (BEFORE INSERT; after layer4_review_items_reroute, before ops_guard_layer4). While layer4.arrival_guard_on
-- is 1, a new waiting item of a kind in layer4.platform_kinds that the platform can settle (security.layer4_resolution_for_v1) arrives superseded,
-- with the reason recorded in pipeline.layer4_supersessions. It never approves, rejects or changes any other row. Every generator passes here.
declare v_res jsonb;
begin
  if new.status is distinct from 'pending' or security.pipeline_num_v1('layer4.arrival_guard_on', 0) < 1
     or not (new.field_code = any (security.pipeline_list_v1('layer4.platform_kinds', '[]'::jsonb))) then
    return new;
  end if;
  new.id := coalesce(new.id, gen_random_uuid());
  v_res := security.layer4_resolution_for_v1(new.id, new.entity_type, new.entity_id, new.field_code, new.proposed_value, new.layer2_state, new.evidence_id, coalesce(new.created_at, now()));
  if v_res is null then return new; end if;
  new.status := 'superseded';
  new.decided_at := now();
  new.change_control_ref := coalesce(new.change_control_ref || '; ', '') || 'CF-247 L4 readiness: settled on arrival (' || (v_res->>'reason') || ')';
  insert into pipeline.layer4_supersessions(item_id, field_code, entity_type, entity_id, reason, covered_by_item, evidence, mode)
  values (new.id, new.field_code, new.entity_type, new.entity_id, v_res->>'reason', nullif(v_res->>'covered_by_item', '')::uuid, coalesce(v_res->'evidence', '{}'::jsonb), 'arrival');
  return new;
end $function$

CREATE OR REPLACE FUNCTION security.layer4_reroute_trg_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.entity_type = 'course' and new.status = 'pending' and security.layer4_reroute_course_v1(new.entity_id, new.field_code, true) then
    new.status := 'superseded'; new.decided_at := now();
    new.change_control_ref := coalesce(new.change_control_ref || '; ', '') || 'CF-247 v2.15.250: rerouted to the university adapter';
    insert into pipeline.layer4_reroutes(item_id, entity_type, entity_id, field_code, route, note) values (new.id, 'course', new.entity_id, new.field_code, 'adapter', 'on arrival');
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION security.manual_fact_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r jsonb; v_field text;
begin
  if coalesce(current_setting('cf.manual_edit', true), '') = 'on' then
    if TG_OP = 'DELETE' then return OLD; end if; return NEW;
  end if;
  if TG_OP = 'DELETE' then r := to_jsonb(OLD); else r := to_jsonb(NEW); end if;
  v_field := case TG_TABLE_NAME
               when 'course_links' then case when r->>'link_type' = 'official_course' then 'official_url' else 'link:' || (r->>'link_type') end
               when 'course_intakes' then 'intakes'
               when 'course_english_requirements' then 'english'
               when 'course_fees' then case when r->>'fee_type' = 'provider_current_tuition' then 'tuition' end end;
  if v_field is not null and exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = (r->>'course_id')::uuid and l.field = v_field) then
    return null;
  end if;
  if TG_OP = 'DELETE' then return OLD; end if;
  return NEW;
end $function$

CREATE OR REPLACE FUNCTION security.ops_guard_settings_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
-- While a remedy runs a setting may change only within its own range, and never: a range (min_value, max_value), a service toolset (paid
-- services), a budget, spend, credit, reserve or ceiling, an admission or Layer 4 setting, the controller's own or the alerts' settings.
declare v_num numeric;
begin
  if TG_OP <> 'UPDATE' then raise exception 'ops guard: a remedy cannot add or remove settings' using errcode = '42501'; end if;
  if new.min_value is distinct from old.min_value or new.max_value is distinct from old.max_value or new.key is distinct from old.key or new.toolset_key is distinct from old.toolset_key then
    raise exception 'ops guard: a remedy cannot change a setting''s range or identity (%.%)', old.toolset_key, old.key using errcode = '42501';
  end if;
  -- fixed: the protected settings are the authority boundary itself; widening or narrowing them is a release, never a setting
  if old.toolset_key <> 'pipeline' or old.key ~ '^(ops|budgets|layer4|alerts|integration|targets)\.'
     or old.key ~* '(budget|_usd|credit|ceiling|reserve|spend|admit|admission|auto_approve|search_per_run|paid)' then
    raise exception 'ops guard: a remedy cannot change % (budgets, admission and controller settings are changed by a person)', old.key using errcode = '42501';
  end if;
  if jsonb_typeof(new.value) = 'number' then
    v_num := (new.value #>> '{}')::numeric;
    if (old.min_value is not null and v_num < old.min_value) or (old.max_value is not null and v_num > old.max_value) then
      raise exception 'ops guard: % must stay within % to %', old.key, old.min_value, old.max_value using errcode = '42501';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION security.sync_evidence_entity_links()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'security'
AS $function$
declare v_old jsonb; v_new jsonb; v_evidence uuid; r record; v_table text:=tg_table_schema||'.'||tg_table_name;
begin
  if tg_op in ('UPDATE','DELETE') then v_old:=to_jsonb(old); v_evidence:=nullif(v_old->>'evidence_id','')::uuid; if v_evidence is not null then for r in select * from security.evidence_row_entity_links(v_table,v_old) loop perform security.adjust_evidence_entity_link(v_evidence,r.entity_type,r.entity_id,r.provider_id,-1); end loop; end if; end if;
  if tg_op in ('INSERT','UPDATE') then v_new:=to_jsonb(new); v_evidence:=nullif(v_new->>'evidence_id','')::uuid; if v_evidence is not null then for r in select * from security.evidence_row_entity_links(v_table,v_new) loop perform security.adjust_evidence_entity_link(v_evidence,r.entity_type,r.entity_id,r.provider_id,1); end loop; end if; end if;
  return case when tg_op='DELETE' then old else new end;
end $function$

CREATE OR REPLACE FUNCTION security.sync_evidence_lineage_stats()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'security'
AS $function$
declare
  v_old jsonb;
  v_new jsonb;
  v_old_evidence uuid;
  v_new_evidence uuid;
  v_table text:=tg_table_schema||'.'||tg_table_name;
begin
  if tg_op in ('UPDATE','DELETE') then
    v_old:=to_jsonb(old);
    v_old_evidence:=nullif(v_old->>'evidence_id','')::uuid;
    perform security.adjust_evidence_lineage_stats(
      v_old_evidence,
      -1,
      case when security.evidence_row_source_null(v_table,v_old) then -1 else 0 end,
      case when security.evidence_row_rejected(v_old) then -1 else 0 end
    );
  end if;
  if tg_op in ('INSERT','UPDATE') then
    v_new:=to_jsonb(new);
    v_new_evidence:=nullif(v_new->>'evidence_id','')::uuid;
    perform security.adjust_evidence_lineage_stats(
      v_new_evidence,
      1,
      case when security.evidence_row_source_null(v_table,v_new) then 1 else 0 end,
      case when security.evidence_row_rejected(v_new) then 1 else 0 end
    );
  end if;
  return case when tg_op='DELETE' then old else new end;
end
$function$

CREATE OR REPLACE FUNCTION public.admin_provider_english_propose(p_provider_id uuid, p_rule jsonb, p_url text, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid; v_src uuid; v_ev uuid; v_defaults jsonb := '{}'::jsonb; v_ex jsonb := '[]'::jsonb; v_prop jsonb; k text; r jsonb; v_note text := btrim(coalesce(p_note, ''));
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if not exists (select 1 from catalogue.providers where id = p_provider_id) then raise exception 'provider not found'; end if;
  if coalesce(btrim(p_url), '') !~* '^https?://' then raise exception 'the central English page address is required'; end if;
  if length(v_note) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  -- one requirement: IELTS overall from 4 to 9 in halves, optional lowest band
  for k in select x from unnest(array['undergraduate', 'postgraduate']) x loop
    r := p_rule->k;
    continue when r is null;
    if (r->>'overall') !~ '^[4-9](\.[05])?$' or coalesce(r->>'min_band', '5') !~ '^[3-9](\.[05])?$' then raise exception 'the % rule needs an IELTS overall (and lowest band) from 4 to 9 in halves', k; end if;
    v_defaults := v_defaults || jsonb_build_object(k, jsonb_build_array(jsonb_build_object('test_code', 'IELTS', 'overall_score', (r->>'overall')::numeric,
                    'component_scores', case when r ? 'min_band' then jsonb_build_object('listening', (r->>'min_band')::numeric, 'reading', (r->>'min_band')::numeric, 'writing', (r->>'min_band')::numeric, 'speaking', (r->>'min_band')::numeric) else '{}'::jsonb end,
                    'quote', left(coalesce(r->>'quote', ''), 400))));
  end loop;
  for r in select e from jsonb_array_elements(coalesce(p_rule->'named', '[]'::jsonb)) e loop
    if length(btrim(coalesce(r->>'name', ''))) < 4 or (r->>'overall') !~ '^[4-9](\.[05])?$' or coalesce(r->>'min_band', '5') !~ '^[3-9](\.[05])?$' then raise exception 'each named course needs a name and an IELTS overall (and lowest band) from 4 to 9 in halves'; end if;
    v_ex := v_ex || jsonb_build_array(jsonb_build_object('name', btrim(r->>'name'), 'level', null, 'reqs', jsonb_build_array(jsonb_build_object('test_code', 'IELTS', 'overall_score', (r->>'overall')::numeric,
              'component_scores', case when r ? 'min_band' then jsonb_build_object('listening', (r->>'min_band')::numeric, 'reading', (r->>'min_band')::numeric, 'writing', (r->>'min_band')::numeric, 'speaking', (r->>'min_band')::numeric) else '{}'::jsonb end,
              'quote', left(coalesce(r->>'quote', ''), 400)))));
  end loop;
  if v_defaults = '{}'::jsonb and jsonb_array_length(v_ex) = 0 then raise exception 'give at least one level rule or named course'; end if;
  v_prop := jsonb_build_object('parser', 'written out from the central page', 'style', case when v_defaults = '{}'::jsonb then 'named_courses' else 'level_default' end,
                               'defaults', v_defaults, 'exceptions', v_ex, 'named', '[]'::jsonb, 'caveats', '[]'::jsonb, 'signals', '[]'::jsonb, 'conflicts', '[]'::jsonb);
  insert into pipeline.provider_fact_sources(provider_id, kind, url, title, rank, found_via, status)
  values (p_provider_id, 'english_policy', btrim(p_url), 'Central English page given by a Platform Admin', 9, 'manual', 'found')
  on conflict on constraint provider_fact_sources_key do nothing;
  select id, evidence_id into v_src, v_ev from pipeline.provider_fact_sources where provider_id = p_provider_id and kind = 'english_policy' and url = btrim(p_url);
  insert into pipeline.provider_policy_proposals(provider_id, fact_source_id, kind, parser, content_hash, evidence_id, url, style, proposal, status, decision_note)
  values (p_provider_id, v_src, 'english_policy', 'written out from the central page', md5(v_prop::text), v_ev, btrim(p_url), v_prop->>'style', v_prop, 'proposed', left(v_note, 500))
  on conflict (fact_source_id, parser, content_hash) do nothing
  returning id into v_id;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('policies', 'english_rule_proposed', btrim(p_url), jsonb_build_object('decision', 'Decision 254', 'proposal_id', v_id, 'provider_id', p_provider_id, 'rule', p_rule, 'note', v_note), auth.uid());
  return jsonb_build_object('id', v_id, 'note', 'Approve or reject it in Layer 4 Review › Attributes.');
end $function$

CREATE OR REPLACE FUNCTION public.admin_provider_policy_decide(p_id uuid, p_action text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare x pipeline.provider_policy_proposals%rowtype; v jsonb := '{}'::jsonb; v_ag int := 0; v_df int := 0; v_sum jsonb;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if p_action not in ('approve', 'reject') then raise exception 'action must be approve or reject'; end if;
  select * into x from pipeline.provider_policy_proposals where id = p_id for update;
  if x.id is null then raise exception 'proposal not found'; end if;
  if x.status <> 'proposed' then raise exception 'already decided or not a proposal (%)', x.status; end if;
  if p_action = 'approve' and x.kind = 'english_policy' then
    v_sum := security.provider_policy_refresh_one_v1(p_id);
    v_ag := coalesce((v_sum->>'agrees')::int, 0); v_df := coalesce((v_sum->>'differs')::int, 0);
    if v_ag + v_df >= 10 and v_df > v_ag then
      raise exception 'This default does not match most course pages (% agree, % differ), so it cannot be approved', v_ag, v_df;
    end if;
  end if;
  update pipeline.provider_policy_proposals set status = case when p_action = 'approve' then 'approved' else 'rejected' end,
         decided_by = auth.uid(), decided_at = now(), decision_note = left(p_note, 500), updated_at = now() where id = p_id;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('policies', p_action, x.kind || ': ' || x.url, jsonb_build_object('decision', 'Decision 227', 'proposal_id', x.id, 'provider_id', x.provider_id), auth.uid());
  -- one approved document per university and kind: its other waiting documents are closed
  if p_action = 'approve' then
    update pipeline.provider_policy_proposals
       set status = 'superseded', decided_at = now(), updated_at = now(),
           decision_note = 'Closed: another document for this university was approved (' || x.url || ')'
     where provider_id = x.provider_id and kind = x.kind and status = 'proposed' and id <> x.id;
  end if;
  if p_action = 'approve' and x.kind = 'english_policy' then v := jsonb_build_object('to_fill', coalesce((v_sum->>'write')::int, 0)); end if;
  if p_action = 'approve' and x.kind = 'intake_calendar' then
    v := jsonb_build_object('to_answer', (select count(*) from security.semester_intake_plan_v1(x.provider_id) r where r.outcome = 'answer'));
  end if;
  return jsonb_build_object('status', case when p_action = 'approve' then 'approved' else 'rejected' end) || v;
end $function$

CREATE OR REPLACE FUNCTION security.english_level_apply_v1(p_provider_id uuid, p_apply boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare x pipeline.provider_policy_proposals%rowtype; r record; v_lv jsonb; v_write jsonb; v_tests text[]; v_src uuid; v_name text; v_out int;
        v_written int := 0; v_same int := 0; v_own_differs int := 0; v_own int := 0; v_held int := 0; v_withdrawn int := 0; v_unknown jsonb := '{}'::jsonb;
        v_courses uuid[] := '{}'; v_err int := 0; v_last text; v_label text; v_k text; v_how text; v_rule text;
        v_day text := to_char(now() at time zone 'Australia/Melbourne', 'FMDD Mon YYYY');
begin
  -- the approved English policy in force that names levels (Decision 262 keeps one in force per level; the latest decision wins here)
  select * into x from pipeline.provider_policy_proposals
   where provider_id = p_provider_id and kind = 'english_policy' and status = 'approved' and jsonb_typeof(proposal->'levels') = 'object'
   order by decided_at desc nulls last limit 1;
  if x.id is null then return jsonb_build_object('skipped', 'no approved English policy with levels'); end if;
  if x.evidence_id is null or coalesce(x.content_hash, '') = '' then return jsonb_build_object('skipped', 'the policy page has no stored evidence'); end if;
  v_src := security.coverage_sweep_source(x.provider_id);
  select coalesce(p.display_name, p.canonical_name) into v_name from catalogue.providers p where p.id = x.provider_id;
  for r in
    select co.id course_id, co.canonical_title title, security.english_level_group(sl.code) grp,
           -- Decision 265: the level the course page names, else the one its companion page names (Melbourne's entry requirements page)
           case when coalesce(g.candidates->'adapter_extra'->>'english_level', '') <> '' then g.candidates->'adapter_extra'->>'english_level'
                when cp.status = 'read' then nullif(cp.values->>'english_level', '') end raw,
           case when coalesce(g.candidates->'adapter_extra'->>'english_level', '') <> '' then g.url else cp.url end page_url,
           exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = co.id and l.field in ('english', 'english_requirements', 'course_english')) locked,
           exists (select 1 from pipeline.layer4_review_items i where i.entity_type = 'course' and i.entity_id = co.id and i.field_code = 'course_english' and i.status = 'pending') in_review
      from catalogue.courses co
      join pipeline.coverage_course_pages g on g.course_id = co.id
      left join pipeline.course_companion_pages cp on cp.course_id = co.id
      left join ref.study_levels sl on sl.id = co.study_level_id
     where co.provider_id = x.provider_id and co.lifecycle_status = 'active' and g.read_status = 'read'
  loop
    v_k := security.english_level_key(r.raw); v_how := format('named on the course page (%s)', r.page_url);
    -- Decision 265: no level named on a page: the policy's course group rules, in order (title pattern, and study level group when given)
    if v_k is null then
      select q->>'level', q->>'group_name' into v_k, v_rule
        from jsonb_array_elements(coalesce(x.proposal->'level_rules', '[]'::jsonb)) with ordinality t(q, n)
       where r.title ~* (q->>'title_regex')
         and (jsonb_typeof(q->'groups') is distinct from 'array' or r.grp in (select jsonb_array_elements_text(q->'groups')))
       order by n limit 1;
      if v_k is null then continue; end if;
      v_k := security.english_level_key(v_k); v_how := format('for this course group ("%s")', v_rule);
    end if;
    v_lv := x.proposal->'levels'->v_k;
    v_label := coalesce(x.proposal->'level_names'->>v_k, btrim(coalesce(r.raw, v_k)));
    if jsonb_typeof(v_lv) is distinct from 'array' or jsonb_array_length(v_lv) = 0 then
      v_unknown := jsonb_set(v_unknown, array[coalesce(v_k, '?')], to_jsonb(coalesce((v_unknown->>coalesce(v_k, '?'))::int, 0) + 1)); continue;
    end if;
    if r.locked or r.in_review then v_held := v_held + 1; continue; end if;
    -- the course page prints its own score for a test of the level, and it differs: the page has its own requirement (an accreditation
    -- standard, for example), so the level is not used for this course and rows this rule wrote before are withdrawn
    if exists (select 1 from jsonb_array_elements(v_lv) q
                join ref.english_tests t on t.code = upper(q->>'test_code')
                join catalogue.course_english_requirements e on e.course_id = r.course_id and e.english_test_id = t.id and e.status = 'active'
               where coalesce(e.source_requirement_key, '') not like 'policy:%' and e.overall_score <> (q->>'overall_score')::numeric) then
      v_own_differs := v_own_differs + 1;
      if p_apply then
        with w as (
          update catalogue.course_english_requirements e set status = 'withdrawn', last_verified_at = now(),
                 notes = coalesce(e.notes, '') || format(' Withdrawn %s: the course page prints its own English score, which differs from level "%s" (Decision 264).', v_day, v_label)
           where e.course_id = r.course_id and e.status = 'active' and e.source_requirement_key like 'policy:%' and e.notes like 'English level %Decision 264%'
          returning e.course_id)
        select count(*) into v_out from w;
        v_withdrawn := v_withdrawn + v_out;
        if v_out > 0 then v_courses := v_courses || r.course_id; end if;
      end if;
      continue;
    end if;
    v_tests := array(select upper(q->>'test_code') from jsonb_array_elements(v_lv) q);
    -- the course's own reading (any key that is not a policy's) is never replaced
    v_own := v_own + (select count(*) from jsonb_array_elements(v_lv) q
                       where exists (select 1 from catalogue.course_english_requirements e join ref.english_tests t on t.id = e.english_test_id
                                      where e.course_id = r.course_id and t.code = upper(q->>'test_code') and e.status = 'active'
                                        and coalesce(e.source_requirement_key, '') not like 'policy:%'))::int;
    select coalesce(jsonb_agg(jsonb_build_object(
             'test_code', upper(q->>'test_code'), 'overall_score', q->'overall_score', 'component_scores', coalesce(q->'component_scores', '{}'::jsonb),
             'source_requirement_key', 'policy:' || x.id || ':' || lower(q->>'test_code'),
             'notes', format('English level "%s" %s; scores for that level from %s''s English language requirements (%s), approved by a Platform Admin (Decision 264, 265).',
                             v_label, v_how, v_name, x.url))), '[]'::jsonb)
      into v_write
      from jsonb_array_elements(v_lv) q
     where upper(q->>'test_code') in (select t.code from ref.english_tests t where t.status = 'active')
       and not exists (select 1 from catalogue.course_english_requirements e join ref.english_tests t on t.id = e.english_test_id
                        where e.course_id = r.course_id and t.code = upper(q->>'test_code') and e.status = 'active'
                          and (coalesce(e.source_requirement_key, '') not like 'policy:%'
                               or (e.source_requirement_key = 'policy:' || x.id || ':' || lower(q->>'test_code')
                                   and e.overall_score is not distinct from (q->>'overall_score')::numeric  -- a level may give skill minimums only (no overall)
                                   and e.component_scores = coalesce(q->'component_scores', '{}'::jsonb)
                                   and e.notes like 'English level %Decision 264%')));
    if jsonb_array_length(v_write) = 0 then v_same := v_same + 1; continue; end if;
    if not p_apply then v_written := v_written + 1; continue; end if;
    begin
      perform security.coverage_apply_course_v1(r.course_id, v_src, x.evidence_id, x.url, x.content_hash, jsonb_build_object('english_requirements', v_write));
      -- policy rows for tests this level does not give are withdrawn (kept, not deleted)
      with w as (
        update catalogue.course_english_requirements e set status = 'withdrawn', last_verified_at = now(),
               notes = coalesce(e.notes, '') || format(' Withdrawn %s: the course page names English level "%s", which does not give this test (Decision 264).', v_day, v_label)
          from ref.english_tests t
         where t.id = e.english_test_id and e.course_id = r.course_id and e.status = 'active'
           and e.source_requirement_key like 'policy:%' and t.code <> all (v_tests)
        returning 1)
      select count(*) into v_out from w;
      v_withdrawn := v_withdrawn + v_out;
      v_written := v_written + 1; v_courses := v_courses || r.course_id;
    exception when others then v_err := v_err + 1; v_last := left(sqlerrm, 200);
    end;
  end loop;
  if cardinality(v_courses) > 0 then
    insert into search.enrichment_source_gates(projection_code, domain_code, source_id, gate_status, approval_ref, approved_at, created_at, updated_at)
    select 'courses', 'course_english', v_src, 'approved', 'CF-CHG-20260915-247; Decision 227 (English from the provider''s policy, approved by a Platform Admin)', now(), now(), now()
     where not exists (select 1 from search.enrichment_source_gates g where g.projection_code = 'courses' and g.domain_code = 'course_english' and g.source_id = v_src);
    perform search.refresh_course_enrichment_scoped_v1(v_courses, true);
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('policies', 'english_levels', 'english_policy: ' || x.url,
            jsonb_build_object('proposal_id', x.id, 'provider_id', x.provider_id, 'courses', cardinality(v_courses), 'withdrawn_rows', v_withdrawn,
                               'unknown_levels', v_unknown, 'decision', 264), null);
  end if;
  update pipeline.provider_policy_proposals
     set apply_summary = coalesce(apply_summary, '{}'::jsonb) || jsonb_build_object('levels', jsonb_build_object(
           'courses_written', v_written, 'unchanged', v_same, 'own_reading_tests', v_own, 'own_differs', v_own_differs, 'held', v_held, 'withdrawn_rows', v_withdrawn,
           'unknown_levels', v_unknown, 'refused', v_err, 'last_error', v_last, 'checked_at', now(), 'applied', p_apply)), updated_at = now()
   where id = x.id and p_apply;
  return jsonb_build_object('policy', x.id, 'courses_written', v_written, 'unchanged', v_same, 'own_reading_tests', v_own, 'own_differs', v_own_differs, 'own_differs', v_own_differs, 'held', v_held,
                            'withdrawn_rows', v_withdrawn, 'unknown_levels', v_unknown, 'refused', v_err, 'last_error', v_last);
end $function$

CREATE OR REPLACE FUNCTION security.english_policy_in_force_all_v1(p_apply boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_pid uuid; v jsonb; v_out jsonb := '[]'::jsonb; v_moved int := 0; v_l4 int := 0; v_closed int := 0; v_levels int := 0;
begin
  for v_pid in
    select pp.provider_id from pipeline.provider_policy_proposals pp, jsonb_object_keys(coalesce(pp.proposal->'defaults', '{}'::jsonb)) lv
     where pp.kind = 'english_policy' and pp.status = 'approved' and lv in ('undergraduate', 'postgraduate', 'research')
       and jsonb_typeof(pp.proposal->'defaults'->lv) = 'array' and jsonb_array_length(pp.proposal->'defaults'->lv) > 0
     group by pp.provider_id, lv having count(*) > 1
  loop
    if exists (select 1 from jsonb_array_elements(v_out) o where o->>'provider_id' = v_pid::text) then continue; end if;
    v := security.english_policy_in_force_v1(v_pid, p_apply);
    v_out := v_out || (v || jsonb_build_object('provider', (select canonical_name from catalogue.providers where id = v_pid)));
    v_levels := v_levels + (v->>'levels')::int; v_moved := v_moved + (v->>'rows_moved')::int; v_l4 := v_l4 + (v->>'layer4')::int; v_closed := v_closed + (v->>'closed')::int;
  end loop;
  if p_apply and jsonb_array_length(v_out) > 0 then
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('policies', 'in_force', 'english_policy', jsonb_build_object('decision', 'Decision 262', 'universities', jsonb_array_length(v_out), 'levels', v_levels,
            'rows_moved', v_moved, 'layer4', v_l4, 'closed', v_closed, 'items', v_out), null);
  end if;
  return jsonb_build_object('universities', jsonb_array_length(v_out), 'levels', v_levels, 'rows_moved', v_moved, 'layer4', v_l4, 'closed', v_closed, 'items', v_out);
end $function$

CREATE OR REPLACE FUNCTION security.enrich_parse_english_v1(p_text text, p_quote text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v_n numeric[]; v_o numeric; v_b numeric;
begin
  if p_quote !~* 'ielts' then return null; end if;
  v_n := array(select m[1]::numeric from regexp_matches(coalesce(p_text, ''), '([4-9](?:\.[05])?)', 'g') m);
  if cardinality(v_n) = 0 then return null; end if;
  v_o := v_n[1]; v_b := case when cardinality(v_n) > 1 and v_n[2] <= v_n[1] then v_n[2] end;
  -- the overall score must be in the quote as written (6.5, or 6 / 6.0)
  if not (p_quote ~ ('(^|[^0-9.])' || replace(v_o::text, '.', '\.') || '([^0-9]|$)') or (v_o = trunc(v_o) and p_quote ~ ('(^|[^0-9.])' || trunc(v_o)::text || '(\.0)?([^0-9.]|$)'))) then return null; end if;
  return jsonb_build_object('overall', v_o, 'band', v_b);
end $function$

CREATE OR REPLACE FUNCTION security.layer4_course_english_apply_impl(p_actor uuid, p_item_id uuid, p_value jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_item pipeline.layer4_review_items%rowtype; x jsonb; v_test uuid; v_n int := 0; v_src uuid;
begin
  select * into v_item from pipeline.layer4_review_items where id = p_item_id;
  if v_item.entity_type <> 'course' then raise exception 'English requirements apply to courses only'; end if;
  if jsonb_typeof(p_value->'english_requirements') <> 'array' or jsonb_array_length(p_value->'english_requirements') = 0 then
    raise exception 'enter at least one English test score, then approve';
  end if;
  select id into v_src from pipeline.sources where source_type = 'layer4_human_review' limit 1;
  for x in select e from jsonb_array_elements(p_value->'english_requirements') e loop
    select id into v_test from ref.english_tests where code = upper(btrim(coalesce(x->>'test_code', x->>'test')));
    if v_test is null then raise exception 'unknown English test %', coalesce(x->>'test_code', x->>'test'); end if;
    if coalesce(x->>'overall_score', x->>'overall', '') !~ '^[0-9]+(\.[0-9]+)?$' then raise exception 'enter an overall score for %', coalesce(x->>'test_code', x->>'test'); end if;
    insert into catalogue.course_english_requirements(course_id, english_test_id, overall_score, component_scores, notes, source_id, evidence_id, confidence,
                                                      source_requirement_key, status, last_verified_at)
    values (v_item.entity_id, v_test, coalesce(x->>'overall_score', x->>'overall')::numeric, coalesce(x->'component_scores', x->'components', '{}'::jsonb),
            'Layer 4 decision: ' || p_reason, v_src, v_item.evidence_id, 1, 'l4:' || v_item.id || ':' || lower(coalesce(x->>'test_code', x->>'test')), 'active', now())
    on conflict (course_id, english_test_id) do update set overall_score = excluded.overall_score, component_scores = excluded.component_scores, notes = excluded.notes,
           source_id = excluded.source_id, evidence_id = excluded.evidence_id, confidence = 1, source_requirement_key = excluded.source_requirement_key,
           status = 'active', last_verified_at = now();
    v_n := v_n + 1;
  end loop;
  insert into pipeline.manual_locks(entity, entity_id, field, mode, set_by) values ('course', v_item.entity_id, 'english', 'value', p_actor)
  on conflict (entity, entity_id, field) do update set mode = excluded.mode, set_by = excluded.set_by, set_at = now();
  perform search.refresh_course_enrichment_scoped_v1(array[v_item.entity_id], true);
  return jsonb_build_object('tests_written', v_n, 'search_refreshed', true);
end $function$

CREATE OR REPLACE FUNCTION security.policy_auto_approve_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record; v_sum jsonb; v_ag int; v_df int; v_ok int := 0; v_refused int := 0;
        v_max numeric := security.pipeline_num_v1('central.max_disagree_pct', 50);
        v_min int := security.pipeline_num_v1('central.min_compare', 10)::int;
        v_note text := 'Automatic: AI reading of the central page, every value quoted on the page (Platform Admin 15 Oct 2026: "Central pages, per course group", "Auto-approve checked AI proposals")';
begin
  if not coalesce((select (s.value #>> '{}')::boolean from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'central.auto_approve'), false) then
    return jsonb_build_object('off', true);
  end if;
  for r in select x.* from pipeline.provider_policy_proposals x
             left join pipeline.enrich_focus_providers f on f.provider_id = x.provider_id
            where x.status = 'proposed' and x.kind in ('english_policy', 'intake_calendar')
              and (x.parser like 'ai:%'
                   -- CF-247 decision 5 Nov 2026 §2: a deterministic dated calendar reading, only when the Platform Admin switches it on
                   or (x.kind = 'intake_calendar' and x.parser = 'provider-policy-calendar-dates-v2' and security.pipeline_num_v1('central.auto_approve_calendar_dates', 0) = 1
                       and security.calendar_scope_v1(x.proposal, x.url, x.parser) = 'main_teaching'))
              -- 23 Oct 2026 (Platform Admin 12:40): English rules for every university, not only the focus list
              and (coalesce(f.in_focus, false)
                   or (x.kind = 'english_policy' and coalesce((select (s.value #>> '{}')::boolean from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'central.auto_approve_english_all'), false)))
            order by f.rank nulls last, x.created_at loop
    if r.kind = 'english_policy' then
      v_sum := security.provider_policy_refresh_one_v1(r.id);
      v_ag := coalesce((v_sum->>'agrees')::int, 0); v_df := coalesce((v_sum->>'differs')::int, 0);
      if v_ag + v_df >= v_min and 100.0 * v_df / (v_ag + v_df) > v_max then
        insert into pipeline.enrichment_flags(entity, entity_key, provider_id, field, reason_code, reason, source)
        values ('policy', r.id::text, r.provider_id, 'english', 'policy_disagrees',
                format('Not approved automatically: %s course pages agree and %s disagree with this default; a person decides (%s)', v_ag, v_df, r.url), 'policy-auto-approve')
        on conflict (entity, entity_key, field, reason_code) do update set reason = excluded.reason, flagged_at = now(), cleared_at = null;
        v_refused := v_refused + 1;
        continue;
      end if;
    end if;
    update pipeline.provider_policy_proposals set status = 'approved', decided_by = null, decided_at = now(), decision_note = v_note, updated_at = now() where id = r.id;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('policies', 'approve', r.kind || ': ' || r.url, jsonb_build_object('decision', 'Platform Admin 15 Oct 2026: automatic approval of checked AI readings', 'proposal_id', r.id, 'provider_id', r.provider_id), null);
    update pipeline.provider_policy_proposals
       set status = 'superseded', decided_at = now(), updated_at = now(), decision_note = 'Closed: another document for this university was approved (' || r.url || ')'
     where provider_id = r.provider_id and kind = r.kind and status = 'proposed' and id <> r.id
       and (r.kind <> 'intake_calendar' or fact_source_id is not distinct from r.fact_source_id);  -- CF-247 5 Nov 2026: one calendar document never closes another's
    v_ok := v_ok + 1;
  end loop;
  return jsonb_build_object('approved', v_ok, 'refused', v_refused);
end $function$

CREATE OR REPLACE FUNCTION security.provider_english_apply_all_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pipeline', 'security'
AS $function$
declare r record; v jsonb; v_total int := 0; v_n int := 0; v_failed int := 0;
begin
  for r in select id from pipeline.provider_policy_proposals where kind = 'english_policy' and status = 'approved' order by decided_at loop
    begin
      v := security.provider_english_apply_v1(r.id); v_total := v_total + coalesce((v->>'written')::int, 0); v_n := v_n + 1;
    exception when others then
      v_failed := v_failed + 1;
      update pipeline.provider_policy_proposals set apply_summary = coalesce(apply_summary, '{}'::jsonb) || jsonb_build_object('last_error', left(sqlerrm, 200), 'last_failed_at', now()), updated_at = now() where id = r.id;
    end;
  end loop;
  return jsonb_build_object('proposals', v_n, 'written', v_total, 'not_applied', v_failed);
end $function$

CREATE OR REPLACE FUNCTION security.provider_english_apply_v1(p_proposal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'catalogue', 'pipeline', 'security', 'search'
AS $function$
declare x pipeline.provider_policy_proposals%rowtype; v_src uuid; v_name text; r record; v_ok int := 0; v_err int := 0; v_courses uuid[] := '{}'; v_last text;
  v_flag boolean; v_flagged int := 0; v_appr text;
begin
  select * into x from pipeline.provider_policy_proposals where id = p_proposal_id;
  if x.id is null or x.kind <> 'english_policy' then raise exception 'not an English policy proposal'; end if;
  if x.status <> 'approved' then raise exception 'proposal is not approved'; end if;
  if x.evidence_id is null then
    select fs.evidence_id into x.evidence_id from pipeline.provider_fact_sources fs where fs.id = x.fact_source_id and fs.url = x.url and fs.evidence_id is not null;
  end if;
  if x.evidence_id is null or coalesce(x.content_hash, '') = '' then raise exception 'the policy document has no stored evidence'; end if;
  v_src := security.coverage_sweep_source(x.provider_id);
  select coalesce(p.display_name, p.canonical_name) into v_name from catalogue.providers p where p.id = x.provider_id;
  v_flag := security.provider_english_flagged(x.proposal);
  -- CF-247 15 Oct: say who approved it
  v_appr := case when x.decided_by is null and coalesce(x.decision_note, '') like 'Automatic:%' then '(approved automatically: every value is quoted on the page; Platform Admin decision 15 Oct 2026)' else '(approved by a Platform Admin, Decision 227)' end;
  -- courses open to international students first
  for r in select pl.* from security.provider_english_plan_v1(p_proposal_id) pl join catalogue.courses co on co.id = pl.course_id
            where pl.outcome = 'write' order by co.open_to_international desc nulls last, pl.title loop
    begin
      perform security.coverage_apply_course_v1(r.course_id, v_src, x.evidence_id, x.url, x.content_hash,
        jsonb_build_object('english_requirements', (select jsonb_agg(jsonb_build_object(
            'test_code', q->>'test_code', 'overall_score', q->'overall_score', 'component_scores', coalesce(q->'component_scores', '{}'::jsonb),
            'source_requirement_key', 'policy:' || x.id || ':' || lower(q->>'test_code'),
            'notes', case when r.plan = 'named' then 'From ' || v_name || '''s English language policy, which names this course ' || v_appr
                          else 'Default for ' || case when r.study_level in ('graduate_certificate', 'graduate_diploma', 'masters', 'masters_coursework', 'masters_extended') then 'postgraduate coursework' when r.study_level in ('doctorate', 'masters_research') then 'research' else 'undergraduate' end
                               || ' courses in ' || v_name || '''s English language policy ' || v_appr
                               || case when v_flag then '. Flagged: this is the university standard; the policy says some courses need more and does not list them, so check the course page' else '' end end))
          from jsonb_array_elements(r.requirements) q where q->>'test_code' in (select code from ref.english_tests))));
      if v_flag and r.plan <> 'named' then
        update catalogue.course_english_requirements set confidence = 0.6
         where course_id = r.course_id and source_requirement_key like 'policy:' || x.id || ':%';
        v_flagged := v_flagged + 1;
      end if;
      v_ok := v_ok + 1; v_courses := v_courses || r.course_id;
    exception when others then v_err := v_err + 1; v_last := left(sqlerrm, 200);
    end;
  end loop;
  if v_ok > 0 then
    insert into search.enrichment_source_gates(projection_code, domain_code, source_id, gate_status, approval_ref, approved_at, created_at, updated_at)
    select 'courses', 'course_english', v_src, 'approved', 'CF-CHG-20260915-247; Decision 227 (English from the provider''s policy, approved by a Platform Admin)', now(), now(), now()
     where not exists (select 1 from search.enrichment_source_gates g where g.projection_code = 'courses' and g.domain_code = 'course_english' and g.source_id = v_src);
    perform search.refresh_course_enrichment_scoped_v1(v_courses, true);
  end if;
  update pipeline.provider_policy_proposals
     set apply_summary = coalesce(apply_summary, '{}'::jsonb) || jsonb_build_object('written', coalesce((apply_summary->>'written')::int, 0) + v_ok,
           'refused', v_err, 'last_error', v_last, 'last_applied_at', now(),
           'flagged', coalesce((apply_summary->>'flagged')::int, 0) + v_flagged), updated_at = now()
   where id = p_proposal_id;
  return jsonb_build_object('written', v_ok, 'refused', v_err, 'last_error', v_last);
end $function$

CREATE OR REPLACE FUNCTION security.provider_policy_refresh_one_v1(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pipeline', 'security'
AS $function$
declare v jsonb;
begin
  select coalesce(jsonb_object_agg(o, n), '{}'::jsonb) into v from (select r.outcome o, count(*) n from security.provider_english_plan_v1(p_id) r group by 1) s;
  update pipeline.provider_policy_proposals set plan_summary = v, plan_at = now() where id = p_id;
  return v;
end $function$

CREATE OR REPLACE FUNCTION public.svc_central_ai_record(p_queue_id bigint, p_parsed jsonb, p_cost numeric, p_error text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q pipeline.central_ai_queue%rowtype; r jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into q from pipeline.central_ai_queue where id = p_queue_id for update;
  if q.id is null then return jsonb_build_object('ok', false); end if;
  if p_error is not null then
    update pipeline.central_ai_queue set state = case when p_error = 'time budget' then 'queued' when attempts >= 3 then 'failed' else 'queued' end,
           attempts = case when p_error = 'time budget' then greatest(attempts - 1, 0) else attempts end, leased_until = null, error = left(p_error, 400), cost_usd = coalesce(cost_usd, 0) + coalesce(p_cost, 0)
     where id = q.id;
    return jsonb_build_object('ok', true, 'status', 'error');
  end if;
  r := public.svc_provider_policy_record(q.fact_source_id, p_parsed);
  if q.kind = 'intake_calendar' then perform security.calendar_reader_findings_record_v1(q.fact_source_id, q.provider_id, p_parsed); end if;  -- CF-247 decision 5 Nov 2026 §7
  update pipeline.central_ai_queue set state = 'done', done_at = now(), leased_until = null, status = r->>'status', cost_usd = coalesce(cost_usd, 0) + coalesce(p_cost, 0), error = null where id = q.id;
  if r->>'status' = 'proposed' then
    update pipeline.provider_onboarding o set stop_reason = 'approve_central', updated_at = now(),
           note = 'The AI read its central pages; approve or reject them in the Adapter builder (1.3) or Providers › Onboarding › Approvals waiting.'
     where o.provider_id = q.provider_id and o.status = 'stopped' and o.stop_reason = 'nothing_ready';
  end if;
  return jsonb_build_object('ok', true, 'status', r->>'status');
end $function$

CREATE OR REPLACE FUNCTION public.svc_english_table_apply(p_provider_cricos text, p_programs jsonb, p_minimum jsonb, p_table1 jsonb, p_table3 jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pipeline', 'security', 'search'
AS $function$
declare v_source uuid; v_e1 uuid; v_e3 uuid; r record; v_ok int:=0; v_skipped jsonb:='[]'::jsonb; v_courses uuid[]:='{}'; v_doc jsonb; v_ev uuid; v_res jsonb;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  -- only courses with no English requirement are written; existing course-page values are never overwritten
  if jsonb_array_length(coalesce(p_programs,'[]'::jsonb))<30 then raise exception 'too few Table 1 programs; apply refused'; end if;
  if not exists(select 1 from jsonb_array_elements(p_minimum) q where q->>'test_code'='IELTS') then raise exception 'minimum IELTS requirement missing; apply refused'; end if;
  select s.id into v_source from pipeline.sources s where s.source_type='provider_english_requirements' and s.metadata->>'provider_cricos'=upper(btrim(p_provider_cricos))
     and exists(select 1 from pipeline.course_fact_source_qualifications q where q.source_id=s.id and q.qualification_status='qualified' and 'english_requirement'=any(q.admitted_domains));
  if v_source is null then raise exception 'no qualified English requirements source for provider %', p_provider_cricos; end if;
  foreach v_doc in array array[p_table1,p_table3] loop
    if coalesce(v_doc->>'storage_path','')='' or coalesce(v_doc->>'sha256','') !~ '^[0-9a-f]{64}$' then raise exception 'stored table file and its SHA-256 are required'; end if;
    select e.id into v_ev from pipeline.evidence_artifacts e where e.source_id=v_source and e.content_hash=v_doc->>'sha256' limit 1;
    if v_ev is null then
      v_ev:=public.svc_coursefacts_register_evidence(v_source,v_doc->>'url',v_doc->>'storage_path',v_doc->>'sha256','application/pdf',
        jsonb_build_object('layer',2,'kind','provider_english_requirements','document',v_doc->>'document','worker','fee-schedule-etl','decision','Decision 162 step 4'));
    end if;
    if v_doc is not distinct from p_table1 then v_e1:=v_ev; else v_e3:=v_ev; end if;
  end loop;
  for r in select * from security.english_table_plan_v1(p_provider_cricos,p_programs,p_minimum)
            where plan in ('table1','minimum') and comparison='none' and course_cricos is not null loop
    begin
      v_res:=public.svc_coursefacts_apply_record(v_source, case when r.plan='table1' then v_e1 else v_e3 end, p_provider_cricos, r.course_cricos,
        'uq-elp:'||r.plan||':'||r.course_cricos, case when r.plan='table1' then p_table1->>'url' else p_table3->>'url' end,
        case when r.plan='table1' then p_table1->>'sha256' else p_table3->>'sha256' end,
        jsonb_build_object('english_requirements',(select jsonb_agg(jsonb_build_object('test_code',q->>'test_code','overall_score',q->'overall_score','component_scores',coalesce(q->'component_scores','{}'::jsonb),
            'source_requirement_key','d162-elp:'||lower(r.course_cricos)||':'||lower(q->>'test_code'),
            'notes',case when r.reason like 'double degree:%' then 'Decision 162: UQ '||r.reason when r.plan='table1' then 'Decision 162: UQ ELP Table 1 (higher-than-minimum) - '||r.program else 'Decision 162: UQ minimum ELP (Procedure cl. 10-11; Table 3)' end))
          from jsonb_array_elements(r.requirements) q),'extraction_worker','fee-schedule-etl','plan',r.plan,'table1_program',r.program), true);
      v_ok:=v_ok+1; v_courses:=v_courses||r.course_id;
    exception when others then v_skipped:=v_skipped||jsonb_build_object('course',r.title,'reason',left(sqlerrm,200));
    end;
  end loop;
  if cardinality(v_courses)>0 then perform search.refresh_course_enrichment_scoped_v1(v_courses,true); end if;
  return jsonb_build_object('applied',v_ok,'skipped',jsonb_array_length(v_skipped),'skipped_detail',v_skipped,'source_id',v_source,'table1_evidence',v_e1,'table3_evidence',v_e3);
end $function$

CREATE OR REPLACE FUNCTION public.svc_provider_english_add_tests_v1(p_proposal_id uuid, p_parser text, p_parsed jsonb, p_error text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare x pipeline.provider_policy_proposals%rowtype; lv text; v_appr jsonb; v_base jsonb; v_new jsonb; v_ia numeric; v_ip numeric; q jsonb; c text;
        v_prop jsonb; v_added jsonb := '[]'::jsonb; v_skipped jsonb := '[]'::jsonb; v_ids uuid[]; v_courses uuid[] := '{}'; v_rows int := 0; v_out int := 0; n int;
        v_scope text[] := array(select jsonb_array_elements_text(coalesce(p_parsed->'add_only', '[]'::jsonb)));
        v_prior jsonb; v_keep text[]; v_day text := to_char(now() at time zone 'Australia/Melbourne', 'FMDD Mon YYYY');
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into x from pipeline.provider_policy_proposals where id = p_proposal_id for update;
  if x.id is null or x.kind <> 'english_policy' or x.status <> 'approved' then return jsonb_build_object('skipped', 'not an approved English policy'); end if;
  v_prior := coalesce(x.proposal->'added_tests'->'added', '[]'::jsonb);
  v_prop := x.proposal - 'added_tests';
  -- take out what this rule added before (it is read again below)
  for lv in select distinct e->>'level' from jsonb_array_elements(v_prior) e loop
    if jsonb_typeof(v_prop->'defaults'->lv) = 'array' then
      v_prop := jsonb_set(v_prop, array['defaults', lv], (select coalesce(jsonb_agg(a), '[]'::jsonb) from jsonb_array_elements(v_prop->'defaults'->lv) a
                                                         where not exists (select 1 from jsonb_array_elements(v_prior) e where e->>'level' = lv and e->>'test_code' = a->>'test_code')));
    end if;
  end loop;
  if p_parsed is not null and p_error is null and cardinality(v_scope) > 0 then
    for lv in select k from jsonb_object_keys(coalesce(p_parsed->'defaults', '{}'::jsonb)) k where k in ('undergraduate', 'postgraduate') loop
      v_base := v_prop->'defaults'->lv;
      if jsonb_typeof(v_base) is distinct from 'array' then
        v_skipped := v_skipped || jsonb_build_object('level', lv, 'why', 'the approved policy has no default for this level'); continue;
      end if;
      v_ia := null; v_ip := null;
      select (e->>'overall_score')::numeric into v_ia from jsonb_array_elements(v_base) e where e->>'test_code' = 'IELTS' limit 1;
      select (e->>'overall_score')::numeric into v_ip from jsonb_array_elements(p_parsed->'defaults'->lv) e where e->>'test_code' = 'IELTS' limit 1;
      if v_ia is null or v_ip is distinct from v_ia then
        v_skipped := v_skipped || jsonb_build_object('level', lv, 'why', format('IELTS on this reading (%s) is not the approved IELTS (%s)', coalesce(v_ip::text, 'none'), coalesce(v_ia::text, 'none')));
        if v_ip is not null and v_ia is not null then
          insert into pipeline.enrichment_flags(entity, entity_key, provider_id, field, reason_code, reason, source)
          values ('policy', x.id::text, x.provider_id, 'english', 'policy_reading_differs',
                  format('The %s IELTS on the stored policy page reads %s; the approved policy holds %s. A person checks the policy (%s)', lv, v_ip, v_ia, x.url), 'policy-add-tests')
          on conflict (entity, entity_key, field, reason_code) do update set reason = excluded.reason, flagged_at = now(), cleared_at = null;
        end if;
        continue;
      end if;
      select coalesce(jsonb_agg(e), '[]'::jsonb) into v_new from jsonb_array_elements(p_parsed->'defaults'->lv) e
       where e->>'test_code' = any (v_scope) and e->>'test_code' in (select t.code from ref.english_tests t where t.status = 'active')
         and not exists (select 1 from jsonb_array_elements(v_base) a where a->>'test_code' = e->>'test_code');
      if jsonb_array_length(v_new) = 0 then continue; end if;
      v_prop := jsonb_set(v_prop, array['defaults', lv], v_base || v_new);
      for q in select e from jsonb_array_elements(v_new) e loop
        with ins as (
          insert into catalogue.course_english_requirements(course_id, english_test_id, overall_score, component_scores, notes, source_id, evidence_id,
                                                            confidence, source_requirement_key, status, last_verified_at)
          select r.course_id, t.id, (q->>'overall_score')::numeric, coalesce(q->'component_scores', '{}'::jsonb),
                 format('%s %s from the same stored page, added %s (the page''s IELTS for this level matches the approved policy).', r.notes, t.name, v_day),
                 r.source_id, r.evidence_id, r.confidence, 'policy:' || x.id || ':' || lower(q->>'test_code'), 'active', now()
            from catalogue.course_english_requirements r
            join ref.english_tests ti on ti.id = r.english_test_id and ti.code = 'IELTS'
            join catalogue.courses co on co.id = r.course_id
            left join ref.study_levels sl on sl.id = co.study_level_id
            join ref.english_tests t on t.code = q->>'test_code'
           where r.source_requirement_key = 'policy:' || x.id || ':ielts' and r.status = 'active' and r.overall_score = v_ia
             and r.notes like 'Default for %'  -- level defaults only: a course the policy names keeps its own requirement
             and case when sl.code in ('bachelor', 'bachelor_honours', 'associate_degree') then 'undergraduate'
                      when sl.code in ('graduate_certificate', 'graduate_diploma', 'masters', 'masters_coursework', 'masters_extended') then 'postgraduate' end = lv
          on conflict (course_id, english_test_id) do update
             set overall_score = excluded.overall_score, component_scores = excluded.component_scores, notes = excluded.notes,
                 evidence_id = excluded.evidence_id, status = 'active', last_verified_at = now()
           where catalogue.course_english_requirements.source_requirement_key = excluded.source_requirement_key  -- only rows this rule wrote
          returning course_id)
        select array_agg(course_id) into v_ids from ins;
        v_rows := v_rows + coalesce(cardinality(v_ids), 0);
        v_courses := v_courses || coalesce(v_ids, '{}');
        v_added := v_added || jsonb_build_object('level', lv, 'test_code', q->>'test_code', 'overall_score', q->'overall_score', 'quote', q->>'quote',
                                                 'courses', coalesce(cardinality(v_ids), 0));
      end loop;
    end loop;
  end if;
  -- a test added before that this reading no longer gives for that level: its rows are withdrawn (kept, not deleted)
  for lv, c in select distinct e->>'level', e->>'test_code' from jsonb_array_elements(v_prior) e loop
    if exists (select 1 from jsonb_array_elements(v_added) a where a->>'level' = lv and a->>'test_code' = c) then continue; end if;
    with w as (
      update catalogue.course_english_requirements r set status = 'withdrawn', last_verified_at = now(),
             notes = r.notes || format(' Withdrawn %s: the stored page read again no longer gives it for this level.', v_day)
        from catalogue.courses co left join ref.study_levels sl on sl.id = co.study_level_id
       where co.id = r.course_id and r.source_requirement_key = 'policy:' || x.id || ':' || lower(c) and r.status = 'active'
         and r.notes like '%from the same stored page, added%'
         and case when sl.code in ('bachelor', 'bachelor_honours', 'associate_degree') then 'undergraduate'
                  when sl.code in ('graduate_certificate', 'graduate_diploma', 'masters', 'masters_coursework', 'masters_extended') then 'postgraduate' end = lv
      returning r.course_id)
    select array_agg(course_id) into v_ids from w;
    n := coalesce(cardinality(v_ids), 0); v_out := v_out + n;
    v_courses := v_courses || coalesce(v_ids, '{}');
  end loop;
  update pipeline.provider_policy_proposals
     set proposal = v_prop || jsonb_build_object('added_tests', jsonb_build_object('parser', p_parser, 'checked_at', now(), 'added', v_added, 'skipped', v_skipped,
                                                                                 'withdrawn_rows', v_out, 'error', p_error)),
         plan_at = case when v_rows + v_out > 0 then null else plan_at end, updated_at = now()
   where id = x.id;
  if cardinality(v_courses) > 0 then
    perform search.refresh_course_enrichment_scoped_v1((select array_agg(distinct cc) from unnest(v_courses) cc), true);
  end if;
  if v_rows + v_out > 0 then
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('policies', 'add_tests', 'english_policy: ' || x.url, jsonb_build_object('proposal_id', x.id, 'provider_id', x.provider_id, 'parser', p_parser,
            'added', v_added, 'rows', v_rows, 'withdrawn_rows', v_out), null);
  end if;
  return jsonb_build_object('added', jsonb_array_length(v_added), 'rows', v_rows, 'withdrawn', v_out, 'skipped', jsonb_array_length(v_skipped));
end $function$

CREATE OR REPLACE FUNCTION public.svc_provider_policy_record(p_source_id uuid, p_parsed jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare f pipeline.provider_fact_sources%rowtype; v_id uuid; v_status text; v_parser text := coalesce(p_parsed->>'parser', 'unknown');
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into f from pipeline.provider_fact_sources where id = p_source_id;
  if f.id is null or f.kind not in ('english_policy', 'intake_calendar') then raise exception 'not an English policy or calendar document'; end if;
  if jsonb_typeof(p_parsed) <> 'object' then raise exception 'parsed result must be an object'; end if;
  v_status := case
    when f.kind = 'english_policy' and (coalesce(p_parsed->'defaults', '{}'::jsonb) <> '{}'::jsonb
           or exists (select 1 from jsonb_array_elements(coalesce(p_parsed->'exceptions', '[]'::jsonb)) e
                       where jsonb_typeof(e->'reqs') = 'array' and jsonb_array_length(e->'reqs') > 0)) then 'proposed'
    when f.kind = 'intake_calendar' and jsonb_array_length(coalesce(p_parsed->'periods', '[]'::jsonb)) > 0 then 'proposed'
    else 'no_values' end;
  insert into pipeline.provider_policy_proposals(provider_id, fact_source_id, kind, parser, content_hash, evidence_id, url, style, proposal, status)
  values (f.provider_id, f.id, f.kind, v_parser, f.content_hash, f.evidence_id, f.url, left(p_parsed->>'style', 40), p_parsed, v_status)
  on conflict on constraint provider_policy_proposals_key do update
     set proposal = excluded.proposal, style = excluded.style, evidence_id = excluded.evidence_id,
         status = case when pipeline.provider_policy_proposals.status in ('proposed', 'no_values') then excluded.status else pipeline.provider_policy_proposals.status end,
         updated_at = now()
  returning id, status into v_id, v_status;
  update pipeline.provider_policy_proposals set status = 'superseded', updated_at = now()
   where fact_source_id = f.id and id <> v_id and status in ('proposed', 'no_values') and parser <> 'written out from the central page';
  return jsonb_build_object('id', v_id, 'status', v_status);
end $function$
